@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + birthDate : date
  + website : string
}

class User {
  + ID : int
  + name : string
  + address : string
}

class BusinessUser {
  + VATNumber : string
}

class RegularUser {}

class Album {
  + trackNumber : int
}

class Single {}

class Hit {}

RegularUser "1" -- "*" Song
BusinessUser "1" -- "*" Song
Song "1" -- "1" Artist
Album "1" -- "*" Hit
Hit "1" -- "0..1" Single

@enduml

